async _copyToFcc(
  fccHeader = this._fcc,
  deliverMode = this._deliverMode,
  createTarget = false
) {
  // Do not let a destination from an earlier attempt make a folder lookup
  // failure appear recoverable.
  this._folderUri = null;
  let folder;
  let folderUri;
  if (fccHeader) {
    folder = createTarget
      ? lazy.MailUtils.getOrCreateFolder(fccHeader)
      : lazy.MailUtils.getExistingFolder(fccHeader);
  }
  if (
    [Ci.nsIMsgSend.nsMsgDeliverNow, Ci.nsIMsgSend.nsMsgSendUnsent].includes(
      deliverMode
    ) &&
    folder
  ) {
    this._folderUri = fccHeader;
  } else {
    this._folderUri = await lazy.MsgUtils.getMsgFolderURIFromPrefs(
      this._userIdentity,
      this._deliverMode
    );
    if (
      (this._deliverMode == Ci.nsIMsgSend.nsMsgSaveAsDraft &&
        this._compFields.draftId) ||
      (this._deliverMode == Ci.nsIMsgSend.nsMsgSaveAsTemplate &&
        this._compFields.templateId)
    ) {
      // Turn the draft/template ID into a folder URI string.
      try {
        // This can fail if the user renames/removed/moved the folder.
        const uri =
          this._deliverMode == Ci.nsIMsgSend.nsMsgSaveAsDraft
            ? this._compFields.draftId
            : this._compFields.templateId;
        folderUri =
          MailServices.messageServiceFromURI(uri).messageURIToMsgHdr(uri)
            .folder.URI;
      } catch (ex) {
        console.warn(ex);
      }
      // Only accept it if it's a subfolder of the identity's draft/template folder.
      if (folderUri?.startsWith(this._folderUri)) {
        this._folderUri = folderUri;
      }
    }
  }
